61	// DiffResult is the full comparison of two reports. It contains no timestamps
62	// and no storage-order artifacts, so comparing the same pair of reports always
63	// renders byte-identical JSON.
64	type DiffResult struct {
65		Before              DiffReportRef `json:"before"`
66		After               DiffReportRef `json:"after"`
67		ArtifactNameChanged bool          `json:"artifactNameChanged"`
68		ArtifactHashChanged bool          `json:"artifactHashChanged"`
69		Results             []RuleDiff    `json:"results"`
70		Summary             DiffSummary   `json:"summary"`
71	}
