73	// validReportID reports whether id is exactly 64 lowercase hex characters.
74	func validReportID(id string) bool {
75		if len(id) != 64 {
76			return false
77		}
78		for _, c := range id {
79			if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
80				return false
81			}
82		}
83		return true
84	}
