87	// are not comparable: duplicate or empty rule ids, empty rule versions,
88	// unknown check statuses, or a tool-missing/timeout check without a note.
89	func validateDiffReport(r Report) error {
90		seen := make(map[string]bool, len(r.Rules))
91		for _, rule := range r.Rules {
92			if rule.ID == "" {
93				return errCorrupt("report " + r.ReportID + " has a rule with an empty id")
94			}
95			if seen[rule.ID] {
96				return errCorrupt("report " + r.ReportID + " has duplicate rule id " + rule.ID)
97			}
98			seen[rule.ID] = true
99			if rule.Version == "" {
100				return errCorrupt("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
101			}
102			switch rule.Status {
103			case StatusUnchecked, StatusPass, StatusDefect:
104			case StatusToolMissing, StatusTimeout:
105				if strings.TrimSpace(rule.Note) == "" {
106					return errCorrupt("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
107				}
108			default:
109				return errCorrupt("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
110			}
111		}
112		return nil
113	}
