115	// LoadReportForDiff loads a stored report for comparison. The id must be 64
116	// lowercase hex characters; the archive is verified against its id and the
117	// rule semantics are validated. The store is only read, never created or
118	// modified.
119	func LoadReportForDiff(dir, id string) (Report, error) {
120		if !validReportID(id) {
121			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
122		}
123		r, err := LoadReport(dir, id)
124		if err != nil {
125			return Report{}, err
126		}
127		if err := validateDiffReport(r); err != nil {
128			return Report{}, err
129		}
130		return r, nil
131	}
