133	// DiffStore loads both reports from the store and compares them. Both reports
134	// are fully verified before any comparison happens; any failure yields an
135	// error and no partial result.
136	func DiffStore(dir, beforeID, afterID string) (DiffResult, error) {
137		before, err := LoadReportForDiff(dir, beforeID)
138		if err != nil {
139			return DiffResult{}, err
140		}
141		after, err := LoadReportForDiff(dir, afterID)
142		if err != nil {
143			return DiffResult{}, err
144		}
145		return DiffReports(before, after), nil
146	}
147	
148	// sameRuleDefinition reports whether two rules with the same id also agree on
149	// version, kind, severity, invariant and ABI requirement. Only then may their
150	// check statuses be compared.
151	func sameRuleDefinition(a, b ReportRule) bool {
152		return a.Version == b.Version &&
153			a.Kind == b.Kind &&
154			a.Severity == b.Severity &&
155			a.Invariant == b.Invariant &&
