181	// are only compared when the full rule definition is identical. Results are
182	// sorted by rule id and independent of the storage order of rules and
183	// findings.
184	func DiffReports(before, after Report) DiffResult {
185		beforeRules := make(map[string]ReportRule, len(before.Rules))
186		for _, r := range before.Rules {
187			beforeRules[r.ID] = r
188		}
189		afterRules := make(map[string]ReportRule, len(after.Rules))
190		for _, r := range after.Rules {
191			afterRules[r.ID] = r
192		}
193		beforeFindings := indexFindings(before.Findings)
194		afterFindings := indexFindings(after.Findings)
195	
196		ids := make([]string, 0, len(beforeRules)+len(afterRules))
197		for id := range beforeRules {
198			ids = append(ids, id)
199		}
200		for id := range afterRules {
201			if _, ok := beforeRules[id]; !ok {
202				ids = append(ids, id)
203			}
204		}
205		sort.Strings(ids)
206	
207		result := DiffResult{
