1	// Package contractsentinel report: content-addressed, persistable audit reports.
2	package contractsentinel
3	
4	import (
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11		"reflect"
12		"sort"
13		"strings"
14	)
15	
16	// Check statuses recorded per rule in a report.
17	const (
18		StatusUnchecked   = "未检查"
19		StatusPass        = "通过"
20		StatusDefect      = "发现缺陷"
21		StatusToolMissing = "工具缺失"
22		StatusTimeout     = "超时"
23	)
24	
25	// ReportArtifact identifies the audited artifact by name and content hash.
26	type ReportArtifact struct {
27		Name string `json:"name"`
28		Hash string `json:"hash"`
29	}
30	
31	// ReportRule is one rule together with the invariant check result. The note
32	// carries the original checker description: counterexample evidence for a
33	// defect, a tool availability remark for 工具缺失, a deadline remark for 超时,
34	// or an optional remark for a passing check. It is empty for reports built
35	// only from invariant booleans.
36	type ReportRule struct {
37		ID          string `json:"id"`
38		Kind        string `json:"kind"`
39		Severity    string `json:"severity"`
40		Invariant   string `json:"invariant"`
41		RequiresABI bool   `json:"requiresABI"`
42		Version     string `json:"version"`
43		Status      string `json:"status"`
44		Note        string `json:"note,omitempty"`
45	}
46	
47	// ReportFinding binds a defect to its artifact, rule, version and evidence.
48	type ReportFinding struct {
49		ArtifactHash string `json:"artifactHash"`
50		RuleID       string `json:"ruleId"`
51		Version      string `json:"version"`
52		Severity     string `json:"severity"`
53		Invariant    string `json:"invariant"`
54		Evidence     string `json:"evidence"`
55	}
56	
57	// Report is the persisted audit result.
58	type Report struct {
59		ReportID string          `json:"reportId"`
60		Artifact ReportArtifact  `json:"artifact"`
61		Rules    []ReportRule    `json:"rules"`
62		Findings []ReportFinding `json:"findings"`
63	}
64	
65	// wireArtifact is the JSON shape of an artifact in an audit submission.
66	type wireArtifact struct {
67		Name     string `json:"name"`
68		ABI      string `json:"abi"`
69		Bytecode string `json:"bytecode"`
70		Source   string `json:"source"`
71	}
72	
73	// wireRule is the JSON shape of a rule in an audit submission.
74	type wireRule struct {
75		ID          string `json:"id"`
76		Kind        string `json:"kind"`
77		Severity    string `json:"severity"`
78		Invariant   string `json:"invariant"`
79		RequiresABI bool   `json:"requiresABI"`
80		Version     string `json:"version"`
81	}
82	
83	// CheckRecord is one imported per-rule check result: the artifact hash and
84	// rule version it was produced against, the conclusion status, and the
85	// original checker note (counterexample, tool or deadline remark).
86	type CheckRecord struct {
87		ArtifactHash string
88		RuleID       string
89		Version      string
90		Status       string
91		Note         string
92	}
93	
94	// wireCheck is the JSON shape of one entry in the checks array.
95	type wireCheck struct {
96		ArtifactHash string `json:"artifactHash"`
97		RuleID       string `json:"ruleId"`
98		Version      string `json:"version"`
99		Status       string `json:"status"`
100		Note         string `json:"note"`
101	}
102	
103	// wireInput is the JSON object accepted by the audit command.
104	type wireInput struct {
105		Artifact   wireArtifact               `json:"artifact"`
106		Rules      []wireRule                 `json:"rules"`
107		Invariants map[string]json.RawMessage `json:"invariants"`
108		Checks     []wireCheck                `json:"checks"`
109	}
110	
111	// ParseAuditInput decodes an audit submission JSON object into domain values.
112	// Invariant values must be JSON booleans; any other type is an error.
113	func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, []CheckRecord, error) {
114		var in wireInput
115		if err := json.Unmarshal(data, &in); err != nil {
116			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
117		}
118		invariants := make(map[string]bool, len(in.Invariants))
119		for key, raw := range in.Invariants {
120			var holds bool
121			if err := json.Unmarshal(raw, &holds); err != nil {
122				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
123			}
124			invariants[key] = holds
125		}
126		artifact := Artifact{
127			Name:     in.Artifact.Name,
128			ABI:      in.Artifact.ABI,
129			Bytecode: in.Artifact.Bytecode,
130			Source:   in.Artifact.Source,
131		}
132		rules := make([]Rule, 0, len(in.Rules))
133		for _, wr := range in.Rules {
134			rules = append(rules, Rule{
135				ID:          wr.ID,
136				Kind:        wr.Kind,
137				Severity:    wr.Severity,
138				Invariant:   wr.Invariant,
139				RequiresABI: wr.RequiresABI,
140				Version:     wr.Version,
141			})
142		}
143		checks := make([]CheckRecord, 0, len(in.Checks))
144		for _, wc := range in.Checks {
145			checks = append(checks, CheckRecord{
146				ArtifactHash: wc.ArtifactHash,
147				RuleID:       wc.RuleID,
148				Version:      wc.Version,
149				Status:       wc.Status,
150				Note:         wc.Note,
151			})
152		}
153		return artifact, rules, invariants, checks, nil
154	}
155	
156	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
157	// bytecode and source strings contribute; field boundaries are explicit
158	// (length-prefixed) so that different splits never collide. The source is
159	// hashed as a field value, never read from disk, and the name does not
160	// participate.
161	func ArtifactHash(a Artifact) string {
162		h := sha256.New()
163		h.Write([]byte("contractsentinel-artifact-v1\n"))
164		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
165			fmt.Fprintf(h, "%d\n", len(field))
166			h.Write([]byte(field))
167		}
168		sum := h.Sum(nil)
169		return hex.EncodeToString(sum)
170	}
171	
172	// validCheckStatus reports whether status is one of the four recorded check
173	// conclusions.
174	func validCheckStatus(status string) bool {
175		switch status {
176		case StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
177			return true
178		}
179		return false
180	}
181	
182	// BuildReport evaluates rules against the artifact and invariant values and
183	// imported check records and produces the report to persist. Insufficient
184	// inputs (missing ABI for a rule that requires it, missing bytecode for a
185	// symbolic rule) fail the whole submission and are never recorded as defects.
186	// Imported checks are validated as a whole: unknown rules, duplicate records,
187	// unknown statuses, missing notes, hash or version mismatches, and a rule
188	// receiving both a check record and an invariant boolean all reject the
189	// submission without producing a report.
190	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
191		if artifact.Name == "" {
192			return Report{}, errInvalid("artifact name is required")
193		}
194		hash := ArtifactHash(artifact)
195		seen := make(map[string]bool, len(rules))
196		ruleByID := make(map[string]Rule, len(rules))
197		for _, rule := range rules {
198			if rule.ID == "" {
199				return Report{}, errInvalid("rule id is required")
200			}
201			if rule.Version == "" {
202				return Report{}, errInvalid("rule " + rule.ID + " version is required")
203			}
204			if seen[rule.ID] {
205				return Report{}, errInvalid("duplicate rule id " + rule.ID)
206			}
207			seen[rule.ID] = true
208			ruleByID[rule.ID] = rule
209			if rule.RequiresABI && artifact.ABI == "" {
210				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
211			}
212			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
213				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
214			}
215		}
216		checkByRule := make(map[string]CheckRecord, len(checks))
217		for _, check := range checks {
218			if check.RuleID == "" {
219				return Report{}, errInvalid("check rule id is required")
220			}
221			rule, ok := ruleByID[check.RuleID]
222			if !ok {
223				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown rule")
224			}
225			if _, dup := checkByRule[check.RuleID]; dup {
226				return Report{}, errInvalid("duplicate check for rule " + check.RuleID)
227			}
228			if check.ArtifactHash != hash {
229				return Report{}, errInvalid("check for rule " + check.RuleID + ": artifact hash mismatch")
230			}
231			if check.Version != rule.Version {
232				return Report{}, errInvalid("check for rule " + check.RuleID + ": version mismatch")
233			}
234			if !validCheckStatus(check.Status) {
235				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown status " + check.Status)
236			}
237			if check.Status != StatusPass && strings.TrimSpace(check.Note) == "" {
238				return Report{}, errInvalid("check for rule " + check.RuleID + ": note is required for status " + check.Status)
239			}
240			if _, hasInvariant := invariants[rule.Invariant]; hasInvariant {
241				return Report{}, errInvalid("rule " + check.RuleID + ": both a check record and an invariant value are provided")
242			}
243			checkByRule[check.RuleID] = check
244		}
245		report := Report{
246			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
247			Rules:    []ReportRule{},
248			Findings: []ReportFinding{},
249		}
250		for _, rule := range rules {
251			status := StatusUnchecked
252			note := ""
253			if check, ok := checkByRule[rule.ID]; ok {
254				status = check.Status
255				note = check.Note
256			} else if holds, checked := invariants[rule.Invariant]; checked {
257				if holds {
258					status = StatusPass
259				} else {
260					status = StatusDefect
261				}
262			}
263			report.Rules = append(report.Rules, ReportRule{
264				ID:          rule.ID,
265				Kind:        rule.Kind,
266				Severity:    rule.Severity,
267				Invariant:   rule.Invariant,
268				RequiresABI: rule.RequiresABI,
269				Version:     rule.Version,
270				Status:      status,
271				Note:        note,
272			})
273			if status == StatusDefect {
274				evidence := note
275				if evidence == "" {
276					evidence = "invariant " + rule.Invariant + " does not hold"
277				}
278				report.Findings = append(report.Findings, ReportFinding{
279					ArtifactHash: hash,
280					RuleID:       rule.ID,
281					Version:      rule.Version,
282					Severity:     rule.Severity,
283					Invariant:    rule.Invariant,
284					Evidence:     evidence,
285				})
286			}
287		}
288		report.ReportID = ReportID(report)
289		return report, nil
290	}
291	
292	// canonicalRule is the order-independent view of a rule used for the id. The
293	// note is omitted when empty so reports built only from invariant booleans
294	// keep their original ids.
295	type canonicalRule struct {
296		ID          string `json:"id"`
297		Kind        string `json:"kind"`
298		Severity    string `json:"severity"`
299		Invariant   string `json:"invariant"`
300		RequiresABI bool   `json:"requiresABI"`
301		Version     string `json:"version"`
302		Status      string `json:"status"`
303		Note        string `json:"note,omitempty"`
304	}
305	
306	// canonicalFinding is the order-independent view of a finding used for the id.
307	type canonicalFinding struct {
308		ArtifactHash string `json:"artifactHash"`
309		RuleID       string `json:"ruleId"`
310		Version      string `json:"version"`
311		Severity     string `json:"severity"`
312		Invariant    string `json:"invariant"`
313		Evidence     string `json:"evidence"`
314	}
315	
316	// canonicalReport is the deterministic content a report id is computed from.
317	type canonicalReport struct {
318		ArtifactHash string             `json:"artifactHash"`
319		Name         string             `json:"name"`
320		Rules        []canonicalRule    `json:"rules"`
321		Findings     []canonicalFinding `json:"findings"`
322	}
323	
324	// canonicalize renders a report into its order-independent form.
325	func canonicalize(report Report) canonicalReport {
326		cr := canonicalReport{
327			ArtifactHash: report.Artifact.Hash,
328			Name:         report.Artifact.Name,
329		}
330		for _, rule := range report.Rules {
331			cr.Rules = append(cr.Rules, canonicalRule{
332				ID: rule.ID, Kind: rule.Kind, Severity: rule.Severity,
333				Invariant: rule.Invariant, RequiresABI: rule.RequiresABI,
334				Version: rule.Version, Status: rule.Status, Note: rule.Note,
335			})
336		}
337		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
338		for _, finding := range report.Findings {
339			cr.Findings = append(cr.Findings, canonicalFinding{
340				ArtifactHash: finding.ArtifactHash, RuleID: finding.RuleID,
341				Version: finding.Version, Severity: finding.Severity,
342				Invariant: finding.Invariant, Evidence: finding.Evidence,
343			})
344		}
345		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
346		return cr
347	}
348	
349	// ReportID returns the content-addressed identifier of a report. The id binds
350	// the artifact hash, name, complete rule definitions, the invariant value
351	// used by each rule (unchecked and explicit pass are distinct), and the
352	// findings. Rule order, invariant key order and unrelated invariant keys do
353	// not influence it.
354	func ReportID(r Report) string {
355		data, err := json.Marshal(canonicalize(r))
356		if err != nil {
357			panic(err) // canonical values are all strings and bools
358		}
359		sum := sha256.Sum256(data)
360		return hex.EncodeToString(sum[:])
361	}
362	
363	// expectedFindings rebuilds the findings that match a report's rules. A
364	// defect imported from a check record carries the checker's note as evidence;
365	// a defect derived from an invariant boolean carries the standard invariant
366	// message.
367	func expectedFindings(r Report) []ReportFinding {
368		var out []ReportFinding
369		for _, rule := range r.Rules {
370			if rule.Status == StatusDefect {
371				evidence := rule.Note
372				if evidence == "" {
373					evidence = "invariant " + rule.Invariant + " does not hold"
374				}
375				out = append(out, ReportFinding{
376					ArtifactHash: r.Artifact.Hash,
377					RuleID:       rule.ID,
378					Version:      rule.Version,
379					Severity:     rule.Severity,
380					Invariant:    rule.Invariant,
381					Evidence:     evidence,
382				})
383			}
384		}
385		return out
386	}
387	
388	// sameFindings compares two finding sets independently of order; nil and empty
389	// slices are treated as equal.
390	func sameFindings(a, b []ReportFinding) bool {
391		if len(a) == 0 && len(b) == 0 {
392			return true
393		}
394		ac := append([]ReportFinding(nil), a...)
395		bc := append([]ReportFinding(nil), b...)
396		sort.Slice(ac, func(i, j int) bool { return ac[i].RuleID < ac[j].RuleID })
397		sort.Slice(bc, func(i, j int) bool { return bc[i].RuleID < bc[j].RuleID })
398		return reflect.DeepEqual(ac, bc)
399	}
400	
401	// verifyReportBytes parses stored bytes and checks they match the id and that
402	// the findings are consistent with the rules.
403	func verifyReportBytes(data []byte, id string) error {
404		var r Report
405		if err := json.Unmarshal(data, &r); err != nil {
406			return errCorrupt("invalid JSON in report " + id + ": " + err.Error())
407		}
408		if r.ReportID != id {
409			return errCorrupt("report id " + r.ReportID + " does not match stored id " + id)
410		}
411		if ReportID(r) != id {
412			return errCorrupt("report content does not match id " + id)
413		}
414		if !sameFindings(expectedFindings(r), r.Findings) {
415			return errCorrupt("report findings do not match rules for id " + id)
416		}
417		return nil
418	}
419	
420	// SaveReport persists a report under the store directory. The store is safe
421	// for concurrent writers: identical reports share one file and all
422	// submissions succeed, different reports never overwrite each other, and
423	// readers only ever observe complete files. A pre-existing file with the same
424	// id must carry the same report; a corrupted archive makes the submission
425	// fail while keeping the original file.
426	func SaveReport(dir string, r Report) error {
427		if r.ReportID == "" {
428			return errInvalid("report id is required")
429		}
430		if err := os.MkdirAll(dir, 0o755); err != nil {
431			return err
432		}
433		finalPath := filepath.Join(dir, r.ReportID+".json")
434		if existing, err := os.ReadFile(finalPath); err == nil {
435			if err := verifyReportBytes(existing, r.ReportID); err != nil {
436				return err
437			}
438			return nil
439		} else if !os.IsNotExist(err) {
440			return err
441		}
442		data, err := json.Marshal(r)
443		if err != nil {
444			return err
445		}
446		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
447		if err != nil {
448			return err
449		}
450		tmpPath := tmp.Name()
451		cleanup := func() { os.Remove(tmpPath) }
452		if _, err := tmp.Write(data); err != nil {
453			tmp.Close()
454			cleanup()
455			return err
456		}
457		if err := tmp.Sync(); err != nil {
458			tmp.Close()
459			cleanup()
460			return err
461		}
462		if err := tmp.Close(); err != nil {
463			cleanup()
464			return err
465		}
466		if err := os.Rename(tmpPath, finalPath); err != nil {
467			cleanup()
468			if existing, readErr := os.ReadFile(finalPath); readErr == nil {
469				if verifyErr := verifyReportBytes(existing, r.ReportID); verifyErr != nil {
470					return verifyErr
471				}
472				return nil
473			}
474			return err
475		}
476		return nil
477	}
478	
479	// LoadReport reads and verifies a report by id. Missing, corrupted or tampered
480	// archives produce a clear error.
481	func LoadReport(dir, id string) (Report, error) {
482		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
483		if err != nil {
484			if os.IsNotExist(err) {
485				return Report{}, errNotFound("report " + id + " not found")
486			}
487			return Report{}, err
488		}
489		var r Report
490		if err := json.Unmarshal(data, &r); err != nil {
491			return Report{}, errCorrupt("invalid JSON in report " + id)
492		}
493		if r.ReportID != id {
494			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
495		}
496		if ReportID(r) != id {
497			return Report{}, errCorrupt("report content does not match id " + id)
498		}
499		if !sameFindings(expectedFindings(r), r.Findings) {
500			return Report{}, errCorrupt("report findings do not match rules for id " + id)
501		}
502		return r, nil
503	}
504	
505	type errNotFound string
506	
507	func (e errNotFound) Error() string { return string(e) }
508	
509	type errCorrupt string
510	
511	func (e errCorrupt) Error() string { return string(e) }
512

