//     old-style boolean-invariant defect uses the standard invariant message.
//
// invalidf builds an input-validity error (the report is the caller's current
// submission); corruptf builds an archive-corruption error (the report was read
// from disk). Rule problems always name the rule id.
func validateReportStructure(r Report, invalidf, corruptf func(string) error) error {
	errf := invalidf
	if errf == nil {
		errf = corruptf
	}
	if !validHash64(r.ReportID) {
		return errf("invalid report id " + r.ReportID + ": want 64 lowercase hex characters")
	}
	if r.Artifact.Name == "" {
		return errf("report " + r.ReportID + " has an empty artifact name")
	}
	if !validHash64(r.Artifact.Hash) {
		return errf("report " + r.ReportID + " artifact hash is not 64 lowercase hex characters")
	}
	if errf == invalidf && ReportID(r) != r.ReportID {
