		}
	}
	// Corrupt.
	path := filepath.Join(dir, good.ReportID+".json")
	original, _ := os.ReadFile(path)
	_ = os.WriteFile(path, []byte(`{broken`), 0o644)
	if _, err := LoadReport(dir, good.ReportID); err == nil {
